import{c as a,Q as t,j as l,m as i}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"功能特性与技术优势 - 专业的 Web3 资产恢复引擎","description":"了解 Hyperliquid 资产恢复机器人的技术特长：全资产支持、高透明度、安全客户端签名技术以及出色的中英双语服务。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/features"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/features"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/features"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/features"}],["meta",{"name":"keywords","content":"自动化恢复技术, 智能签名模块, Web3找回工具, 去中心化资产挽救"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"功能特性与技术优势 - 专业的 Web3 资产恢复引擎"}],["meta",{"property":"og:description","content":"了解 Hyperliquid 资产恢复机器人的技术特长：全资产支持、高透明度、安全客户端签名技术以及出色的中英双语服务。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/features"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"功能特性与技术优势 - 专业的 Web3 资产恢复引擎"}],["meta",{"name":"twitter:description","content":"了解 Hyperliquid 资产恢复机器人的技术特长：全资产支持、高透明度、安全客户端签名技术以及出色的中英双语服务。"}]]},"headers":[],"relativePath":"zh/features.md","filePath":"zh/features.md","lastUpdated":null}'),r={name:"zh/features.md"};function o(n,e,h,u,d,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h1><p>本页聚焦“能力范围与边界”，帮助您判断机器人是否适用于当前地址。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li>多类账户资产检测：Spot / Perp / Vault / Staked</li><li>标准化恢复执行：7 步自动化流程</li><li>统一费用显示：Service Fee / Withdrawal Fees / Total Cost / You Will Receive</li><li>执行状态反馈：步骤级状态与建议动作</li><li>链上可验证：提供交易哈希用于审计</li></ul><h2 id="支持场景" tabindex="-1">支持场景 <a class="header-anchor" href="#支持场景" aria-label="Permalink to &quot;支持场景&quot;">​</a></h2><ul><li>地址被标记，通常难以在前端完成常规操作</li><li>需要将多类型资产归集为 USDC 并提现</li><li>需要对恢复结果进行可追溯核验</li></ul><h2 id="协议边界" tabindex="-1">协议边界 <a class="header-anchor" href="#协议边界" aria-label="Permalink to &quot;协议边界&quot;">​</a></h2><ul><li>不绕过协议限制：锁仓、等待期、最小提现限制均按平台规则执行</li><li>锁定资产不会提前提取，需到期后重试</li><li>质押资产根据状态可能需要 2-3 次运行</li></ul><h2 id="费用透明" tabindex="-1">费用透明 <a class="header-anchor" href="#费用透明" aria-label="Permalink to &quot;费用透明&quot;">​</a></h2><ul><li>服务费（<code>Service Fee</code>）：0.5%，最低 1 USDC</li><li>提现手续费（<code>Withdrawal Fees</code>）：2 USDC（两次提现）</li><li>总成本（<code>Total Cost</code>）与预计到账（<code>You Will Receive</code>）会在执行前后统一展示</li><li>执行前显示预估，执行后显示实际</li></ul><h2 id="安全策略" tabindex="-1">安全策略 <a class="header-anchor" href="#安全策略" aria-label="Permalink to &quot;安全策略&quot;">​</a></h2><ul><li>仅使用官方机器人入口</li><li>除机器人内正式恢复流程外，不要提供私钥或助记词</li><li>请以交易哈希和链上结果核对执行结果</li></ul><h2 id="不包含的能力" tabindex="-1">不包含的能力 <a class="header-anchor" href="#不包含的能力" aria-label="Permalink to &quot;不包含的能力&quot;">​</a></h2><ul><li>不提供投资建议</li><li>不代替链上协议本身的解锁与等待机制</li><li>不保证外部网络异常下的即时完成</li></ul><h2 id="推荐阅读" tabindex="-1">推荐阅读 <a class="header-anchor" href="#推荐阅读" aria-label="Permalink to &quot;推荐阅读&quot;">​</a></h2><ul><li><a href="./asset-recovery">资产恢复</a></li><li><a href="./fee-and-settlement">费用与到账</a></li><li><a href="./security-and-privacy">安全与隐私</a></li></ul>',16)])])}const f=a(r,[["render",o]]);export{p as __pageData,f as default};
